import React, { useMemo, useState } from "react";
import { User } from "../pages/Users";

interface Column {
  label: string;
  key: keyof User;
}

interface Props {
  data: User[];
  columns: Column[];
  onSort: (key: keyof User) => void;
  sortConfig?: { key: keyof User; direction: "asc" | "desc" } | null;
  rowsPerPage?: number;
  onViewUser?: (user: User) => void;
  onSuspendUser?: (user: User) => void;
}

/* ─── Status ─────────────────────────────────────────────────── */
type Status = "active" | "suspended" | "pending";

function deriveStatus(user: User): Status {
  if (user.location_allowed === true) return "active";
  if (user.location_allowed === false) return "suspended";
  return "pending";
}

const STATUS_STYLES: Record<Status, React.CSSProperties> = {
  active:    { background: "#DCFCE7", color: "#16A34A" },
  suspended: { background: "#FEE2E2", color: "#DC2626" },
  pending:   { background: "#FEF9C3", color: "#CA8A04" },
};

const StatusBadge: React.FC<{ status: Status }> = ({ status }) => (
  <span
    style={{
      ...STATUS_STYLES[status],
      padding: "3px 12px",
      borderRadius: 20,
      fontSize: 12,
      fontWeight: 600,
      letterSpacing: 0.2,
      display: "inline-block",
    }}
  >
    {status.charAt(0).toUpperCase() + status.slice(1)}
  </span>
);

/* ─── Avatar ─────────────────────────────────────────────────── */
const Avatar: React.FC<{ src?: string | null; name: string }> = ({ src, name }) => {
  const initials = name.split(" ").map((w) => w[0]).join("").slice(0, 2).toUpperCase();
  return src ? (
    <img
      src={src}
      alt={name}
      style={{ width: 36, height: 36, borderRadius: "50%", objectFit: "cover", border: "2px solid #F1F5F9", flexShrink: 0 }}
      onError={(e) => { (e.currentTarget as HTMLImageElement).style.display = "none"; }}
    />
  ) : (
    <div
      style={{
        width: 36, height: 36, borderRadius: "50%", background: "#E2E8F0",
        display: "flex", alignItems: "center", justifyContent: "center",
        fontSize: 13, fontWeight: 700, color: "#64748B", flexShrink: 0,
      }}
    >
      {initials || "?"}
    </div>
  );
};

/* ─── Icon button ────────────────────────────────────────────── */
const IconBtn: React.FC<{ title: string; onClick: () => void; children: React.ReactNode }> = ({
  title, onClick, children,
}) => {
  const [hovered, setHovered] = useState(false);
  return (
    <button
      title={title}
      onClick={onClick}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        width: 32, height: 32, border: "1.5px solid #E2E8F0", borderRadius: "50%",
        background: hovered ? "#F8FAFC" : "#fff", cursor: "pointer",
        display: "flex", alignItems: "center", justifyContent: "center",
        transition: "background 0.15s", padding: 0,
      }}
    >
      {children}
    </button>
  );
};

/* ─── Sort icon ──────────────────────────────────────────────── */
const SortIcon: React.FC<{ active: boolean; direction?: "asc" | "desc" }> = ({ active, direction }) => (
  <svg width="13" height="13" viewBox="0 0 13 13" fill="none">
    <path d="M6.5 2v9M6.5 2L4 5M6.5 2L9 5"
      stroke={active && direction === "asc" ? "#EA580C" : "#CBD5E1"}
      strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
    <path d="M6.5 11L4 8M6.5 11L9 8"
      stroke={active && direction === "desc" ? "#EA580C" : "#CBD5E1"}
      strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);

/* ─── Page button ────────────────────────────────────────────── */
const PageBtn: React.FC<{ label: string; active?: boolean; disabled?: boolean; onClick: () => void }> = ({
  label, active = false, disabled = false, onClick,
}) => (
  <button
    onClick={onClick}
    disabled={disabled}
    style={{
      minWidth: 34, height: 34, borderRadius: 8,
      border: active ? "none" : "1px solid #E2E8F0",
      background: active ? "#EA580C" : disabled ? "#F8FAFC" : "#fff",
      color: active ? "#fff" : disabled ? "#CBD5E1" : "#334155",
      fontWeight: 600, fontSize: 13, cursor: disabled ? "not-allowed" : "pointer",
      padding: "0 8px", transition: "background 0.15s",
    }}
  >
    {label}
  </button>
);

/* ─── Main ───────────────────────────────────────────────────── */
export const UserTable: React.FC<Props> = ({
  data, columns, onSort, sortConfig,
  rowsPerPage = 10,
  onViewUser, onSuspendUser,
}) => {
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  const totalPages = Math.max(1, Math.ceil(data.length / rowsPerPage));

  const paginatedData = useMemo(() => {
    const start = (currentPage - 1) * rowsPerPage;
    return data.slice(start, start + rowsPerPage);
  }, [data, currentPage, rowsPerPage]);

  const allSelected =
    paginatedData.length > 0 && paginatedData.every((u) => selectedIds.has(u.id));

  const toggleAll = () =>
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (allSelected) paginatedData.forEach((u) => next.delete(u.id));
      else paginatedData.forEach((u) => next.add(u.id));
      return next;
    });

  const toggleOne = (id: string) =>
    setSelectedIds((prev) => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });

  const pageNumbers = useMemo(() => {
    if (totalPages <= 5) return Array.from({ length: totalPages }, (_, i) => i + 1);
    if (currentPage <= 3) return [1, 2, 3, 4, 5];
    if (currentPage >= totalPages - 2)
      return [totalPages - 4, totalPages - 3, totalPages - 2, totalPages - 1, totalPages];
    return [currentPage - 2, currentPage - 1, currentPage, currentPage + 1, currentPage + 2];
  }, [currentPage, totalPages]);

  const sortTh = (key: keyof User, label: string) => (
    <th style={{ ...thBase, cursor: "pointer" }} onClick={() => onSort(key)}>
      <div style={thInner}>
        {label}
        <SortIcon
          active={sortConfig?.key === key}
          direction={sortConfig?.key === key ? sortConfig.direction : undefined}
        />
      </div>
    </th>
  );

  return (
    <div
      style={{
        fontFamily: "'DM Sans', 'Helvetica Neue', sans-serif",
        width: "100%",
        display: "flex",
        flexDirection: "column",
        background: "#fff",
        borderRadius: 16,
        border: "1px solid #E8EDF2",
        boxShadow: "0 1px 4px rgba(15,23,42,0.06)",
        overflow: "hidden",
      }}
    >
      <div style={{ overflowX: "auto", width: "100%" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", minWidth: 960 }}>
          <thead>
            <tr style={{ background: "#F8FAFC" }}>
              {/* Checkbox */}
              <th style={{ ...thBase, width: 48 }}>
                <input type="checkbox" checked={allSelected} onChange={toggleAll}
                  style={{ cursor: "pointer", accentColor: "#EA580C" }} />
              </th>

              {/* Sr. No. */}
              <th style={{ ...thBase, width: 72 }}>Sr. No.</th>

              {/* Username */}
              {sortTh("name", "Username")}

              {/* Dynamic columns */}
              {columns.map((col) => (
                <th key={String(col.key)} style={{ ...thBase, cursor: "pointer" }} onClick={() => onSort(col.key)}>
                  <div style={thInner}>
                    {col.label}
                    <SortIcon
                      active={sortConfig?.key === col.key}
                      direction={sortConfig?.key === col.key ? sortConfig.direction : undefined}
                    />
                  </div>
                </th>
              ))}

              {/* Status */}
              {sortTh("location_allowed", "Status")}

              {/* Joined Date */}
              {sortTh("created_at", "Joined Date")}

              {/* Action */}
              <th style={{ ...thBase, textAlign: "right" }}>Action</th>
            </tr>
          </thead>

          <tbody>
            {paginatedData.length === 0 ? (
              <tr>
                <td colSpan={columns.length + 6}
                  style={{ padding: "48px 0", textAlign: "center", color: "#94A3B8", fontSize: 14 }}>
                  No users found
                </td>
              </tr>
            ) : (
              paginatedData.map((user, idx) => {
                const status = deriveStatus(user);
                const globalIdx = (currentPage - 1) * rowsPerPage + idx + 1;
                const isSelected = selectedIds.has(user.id);

                return (
                  <tr
                    key={user.id}
                    style={{ background: isSelected ? "#FFF7ED" : "#fff", transition: "background 0.12s" }}
                    onMouseEnter={(e) => { if (!isSelected) e.currentTarget.style.background = "#FAFBFC"; }}
                    onMouseLeave={(e) => { e.currentTarget.style.background = isSelected ? "#FFF7ED" : "#fff"; }}
                  >
                    {/* Checkbox */}
                    <td style={tdBase}>
                      <input type="checkbox" checked={isSelected} onChange={() => toggleOne(user.id)}
                        style={{ cursor: "pointer", accentColor: "#EA580C" }} />
                    </td>

                    {/* Sr. No. */}
                    <td style={{ ...tdBase, color: "#94A3B8", fontSize: 13 }}>
                      {String(globalIdx).padStart(2, "0")}
                    </td>

                    {/* Username + avatar */}
                    <td style={tdBase}>
                      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                        <Avatar src={user.image_url} name={user.name} />
                        <div>
                          <div style={{ fontWeight: 600, fontSize: 14, color: "#0F172A" }}>
                            {user.name || "—"}
                          </div>
                          {user.professional_headline && (
                            <div style={{ fontSize: 11, color: "#94A3B8", marginTop: 1 }}>
                              {user.professional_headline}
                            </div>
                          )}
                        </div>
                      </div>
                    </td>

                    {/* Dynamic columns */}
                    {columns.map((col) => {
                      const val = user[col.key];
                      let display: React.ReactNode = <span style={{ color: "#CBD5E1" }}>—</span>;
                      if (val !== null && val !== undefined && val !== "") {
                        if (Array.isArray(val)) display = val.length ? val.join(", ") : display;
                        else if (typeof val === "boolean") display = val ? "Yes" : "No";
                        else display = String(val);
                      }
                      return (
                        <td key={String(col.key)} style={{ ...tdBase, color: "#475569" }}>
                          {display}
                        </td>
                      );
                    })}

                    {/* Status */}
                    <td style={tdBase}><StatusBadge status={status} /></td>

                    {/* Joined Date */}
                    <td style={{ ...tdBase, color: "#475569", whiteSpace: "nowrap" }}>
                      {user.created_at
                        ? new Date(user.created_at).toLocaleDateString("en-GB")
                        : <span style={{ color: "#CBD5E1" }}>—</span>}
                    </td>

                    {/* Actions */}
                    <td style={{ ...tdBase, textAlign: "right" }}>
                      <div style={{ display: "flex", gap: 8, justifyContent: "flex-end" }}>
                        <IconBtn title="View details" onClick={() => onViewUser?.(user)}>
                          <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                            <circle cx="8" cy="8" r="7" stroke="#94A3B8" strokeWidth="1.5" />
                            <path d="M8 7v4" stroke="#94A3B8" strokeWidth="1.5" strokeLinecap="round" />
                            <circle cx="8" cy="5" r="0.75" fill="#94A3B8" />
                          </svg>
                        </IconBtn>
                        <IconBtn
                          title={status === "suspended" ? "Unsuspend user" : "Suspend user"}
                          onClick={() => onSuspendUser?.(user)}
                        >
                          <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                            <circle cx="8" cy="8" r="7" stroke="#94A3B8" strokeWidth="1.5" />
                            <path d="M3.5 3.5l9 9" stroke="#94A3B8" strokeWidth="1.5" strokeLinecap="round" />
                          </svg>
                        </IconBtn>
                      </div>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {/* PAGINATION */}
      {totalPages > 1 && (
        <div
          style={{
            padding: "14px 20px", borderTop: "1px solid #F1F5F9",
            display: "flex", justifyContent: "space-between",
            alignItems: "center", flexWrap: "wrap", gap: 12,
          }}
        >
          <span style={{ fontSize: 13, color: "#94A3B8" }}>
            Showing {(currentPage - 1) * rowsPerPage + 1}–
            {Math.min(currentPage * rowsPerPage, data.length)} of {data.length} users
          </span>

          <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
            <PageBtn label="←" disabled={currentPage === 1} onClick={() => setCurrentPage((p) => Math.max(p - 1, 1))} />

            {pageNumbers[0] > 1 && (
              <>
                <PageBtn label="1" onClick={() => setCurrentPage(1)} />
                {pageNumbers[0] > 2 && <span style={{ padding: "0 4px", color: "#94A3B8" }}>…</span>}
              </>
            )}

            {pageNumbers.map((p) => (
              <PageBtn key={p} label={String(p)} active={p === currentPage} onClick={() => setCurrentPage(p)} />
            ))}

            {pageNumbers[pageNumbers.length - 1] < totalPages && (
              <>
                {pageNumbers[pageNumbers.length - 1] < totalPages - 1 && (
                  <span style={{ padding: "0 4px", color: "#94A3B8" }}>…</span>
                )}
                <PageBtn label={String(totalPages)} onClick={() => setCurrentPage(totalPages)} />
              </>
            )}

            <PageBtn label="→" disabled={currentPage === totalPages}
              onClick={() => setCurrentPage((p) => Math.min(p + 1, totalPages))} />
          </div>
        </div>
      )}
    </div>
  );
};

/* ─── Style constants ────────────────────────────────────────── */
const thBase: React.CSSProperties = {
  padding: "13px 16px",
  textAlign: "left",
  borderBottom: "1px solid #E8EDF2",
  color: "#64748B",
  fontWeight: 500,
  fontSize: 13,
  userSelect: "none",
  whiteSpace: "nowrap",
};

const thInner: React.CSSProperties = {
  display: "flex",
  alignItems: "center",
  gap: 6,
};

const tdBase: React.CSSProperties = {
  padding: "14px 16px",
  borderBottom: "1px solid #F1F5F9",
  fontSize: 14,
  verticalAlign: "middle",
};
